#include "bits/stdc++.h"

using namespace std;

int main() {
    int x, y;
    cin >> x >> y;
    if (x == 0 && y == 0) {
        cout << 0 << '\n';
    } else if (-x + 1 < y && y <= x) {
        cout << 1 + (x - 1) * 4 << '\n';
    } else if (-y <= x && x < y) {
        cout << 2 + (y - 1) * 4 << '\n';
    } else if (x <= y && y < -x) {
        cout << 3 + (-x - 1) * 4 << '\n';
    } else {
        cout << 4 + (-y - 1) * 4 << '\n';
    }

    return 0;
}

#include "bits/stdc++.h"

using namespace std;

int main() {
    int n, t;
    cin >> n >> t;
    vector<int> a(n);
    for (int& k : a)
        cin >> k;

    int r = 0;
    int sm = 0;
    int ans = 0;
    for (int i = 0; i < n; ++i) {
        while (r < n && sm + a[r] <= t) {
            sm += a[r];
            ++r;
        }
        ans = max(ans, r - i);
        sm -= a[i];
    }

    cout << ans << '\n';

    return 0;
}

#include "bits/stdc++.h"

using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    for (int& k : a)
        cin >> k;

    vector<int> tor(n), tol(n);
    iota(tol.begin(), tol.end(), 0);
    iota(tor.begin(), tor.end(), 0);

    tol[0] = 0;
    for (int i = 1; i < n; ++i)
        if (a[i - 1] >= a[i])
            tol[i] = tol[i - 1];

    tor[n - 1] = n - 1;
    for (int i = n - 2; i >= 0; --i)
        if (a[i] <= a[i + 1])
            tor[i] = tor[i + 1];

    while (m--) {
        int l, r;
        cin >> l >> r;
        --l; --r;
        cout << (tol[r] <= tor[l] ? "Yes" : "No") << '\n';
    }

    return 0;
}

#include "bits/stdc++.h"

using namespace std;

int main() {
    int n;
    cin >> n;
    vector<int> a(n);
    for (int& k : a)
        cin >> k;

    auto vals = a;
    vals.push_back(0);
    sort(vals.begin(), vals.end());
    vals.erase(unique(vals.begin(), vals.end()), vals.end());

    vector<int> pos(n);
    for (int i = 0; i < n; ++i) {
        pos[i] = lower_bound(vals.begin(), vals.end(), a[i]) - vals.begin();
    }

    vector<int> possible(1 << vals.size(), 0);
    for (int i = 1; i < possible.size(); ++i) {
        int k = 0;
        for (int j = 0; j < vals.size() && k < 3; ++j) {
            if ((i >> j) & 1) {
                possible[i] |= possible[i ^ (1 << j)];
                ++k;
            }
        }
        if (__builtin_popcount(i) <= 2) {
            for (int j = 0; j < vals.size(); ++j) {
                if (!((i >> j) & 1)) continue;
                for (int k = 0; k < vals.size(); ++k) {
                    if (!((i >> k) & 1)) continue;
                    int val = vals[j] + vals[k];
                    int ind = lower_bound(vals.begin(), vals.end(), val) - vals.begin();
                    if (ind < vals.size() && vals[ind] == val)
                        possible[i] |= (1 << ind);
                }
            }
        }
    }

    vector<char> dp_cur(1 << vals.size(), 0);
    dp_cur[1 << pos[0]] = 1;
    dp_cur[(1 << pos[0]) | (1 << 0)] = 1;

    auto can_sum = [&](int mask, int pos) {
        return (possible[mask] >> pos) & 1;
    };

    vector<char> dp_next;
    for (int i = 1; i < n; ++i) {
        dp_next.assign(dp_cur.size(), false);
        for (int j = 0; j < dp_cur.size(); ++j) {
            if (dp_cur[j] && can_sum(j, pos[i])) {
                int mask = j;
                mask |= (1 << pos[i]);
                dp_next[mask] = 1;
                for (int k = 0; k < vals.size(); ++k)
                    if (((mask >> k) & 1) && vals[k] != a[i])
                        dp_next[mask ^ (1 << k)] = 1;
            }
        }
        swap(dp_cur, dp_next);
    }

    int ans = -1;
    for (int i = 0; i < dp_cur.size(); ++i) {
        if (!dp_cur[i]) continue;
        int sz = __builtin_popcount(i);
        if (ans == -1 || ans > sz)
            ans = sz;
    }
    cout << ans << '\n';

    return 0;
}

#include "bits/stdc++.h"

using namespace std;

int main() {
    string n;
    cin >> n;
    string m = n;
    {
        for (char& c : m) {
            c ^= '1' ^ '0';
        }
        int ind = m.size() - 1;
        while (ind >= 0 && m[ind] == '1') {
            m[ind] = '0';
            --ind;
        }
        if (ind == -1) {
            m.insert(m.begin(), '1');
            n.insert(n.begin(), '0');
        } else {
            m[ind] = '1';
        }
    }

    int sz = n.size();

    vector<string> v = {n, m};
    vector<array<int, 2>> dp(sz);

    dp[sz - 1][0] = (v[0].back() == '1');
    dp[sz - 1][1] = (v[1].back() == '1');

    for (int i = sz - 2; i >= 0; --i) {
        for (int b = 0; b < 2; ++b) {
            if (v[b][i] == '0') {
                dp[i][b] = dp[i + 1][b];
            } else {
                dp[i][b] = min(dp[i + 1][b] + 1, dp[i + 1][b ^ 1] + 1);
            }
        }
    }

    cout << dp[0][0] << '\n';

    return 0;
}
